package ama.storage;
import ama.transcript.*;import ama.task.*;import ama.model.*;import ama.worker.*;import java.util.*;import java.util.concurrent.atomic.*;import java.nio.file.*;import static org.junit.jupiter.api.Assertions.*;
/** Real observation commit succeeds before its acknowledgment is lost; retry carries the SAME private receipt. */
class Task09ObservationCommitAckIT extends Task09GenerationRichIT {
 final AtomicBoolean armed=new AtomicBoolean(),injected=new AtomicBoolean();ExternalTaskExecution actual;
 @Override javax.sql.DataSource createSource(){return new Task09TraceSource(ama.minutes.Task09Source.open());}
 @Override void externalStarted(ExternalTaskExecution value){actual=value;}
 @Override void beforeWorker(String task){var trace=(Task09TraceSource)source;trace.before=sql->{if(sql.startsWith("INSERT INTO generation_candidate"))armed.set(true);};trace.afterCommit=()->{if(armed.get()&&injected.compareAndSet(false,true))throw new IllegalStateException("TASK09_COMMITTED_OBSERVATION_ACK_LOST");};}
 @Override void afterWorker(String task,MinutesExternalPreparation preparation,ControlledMinutesClient client,JdbcExternalOperations operations,JdbcModelPermitPool permits,Throwable failure)throws Exception{
  assertTrue(injected.get());assertNotNull(failure);var before=j.queryForMap("SELECT * FROM generation_candidate WHERE task_id=?",task);assertEquals("SUCCEEDED",j.queryForObject("SELECT state FROM durable_task WHERE id=?",String.class,task));var field=ExternalExecutionSession.class.getDeclaredField("pending");field.setAccessible(true);var pending=(ExternalOperationPort.PreparedObservation)field.get(actual);assertNotNull(pending);var providerFiles=seals();try{assertEquals(ama.contract.ExternalContracts.ObservationResult.APPLIED,actual.observe(pending));assertEquals(before,j.queryForMap("SELECT * FROM generation_candidate WHERE task_id=?",task));assertEquals(providerFiles,seals());Files.writeString(receipt.resolve("actual-observation-commit-ack-recovery.json"),json.writeValueAsString(Map.of("task",task,"candidate",before.get("id"),"commitReallySucceeded",true,"samePrivateReceipt",true,"sameCandidate",true,"providerUnchanged",true)));}finally{for(int n=0;n<8&&j.queryForObject("SELECT COUNT(*) FROM model_reservation r JOIN external_execution e ON e.id=r.execution_id WHERE e.task_id=? AND r.settled_at IS NULL",Integer.class,task)>0;n++)permits.recoverSettlements(64);assertEquals(0,j.queryForObject("SELECT COUNT(*) FROM model_reservation r JOIN external_execution e ON e.id=r.execution_id WHERE e.task_id=? AND r.settled_at IS NULL",Integer.class,task));}
 }
 Map<String,String> seals()throws Exception{var out=new TreeMap<String,String>();try(var files=Files.walk(providerStore)){for(var file:files.filter(Files::isRegularFile).toList())out.put(providerStore.relativize(file).toString(),HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(file))));}return out;}
}
